const eventBoxDrawLimit = box => box.bonusKey && box.bonusEvery ? 10 : EVENT_BOX_MAX_DRAW;
function eventBoxDrawHash(value) {
  requireValue(sameKeys(value, ['eventBoxId','drawCount']) && Number.isSafeInteger(value.eventBoxId) && value.eventBoxId > 0 &&
    Number.isSafeInteger(value.drawCount) && value.drawCount >= 1 && value.drawCount <= EVENT_BOX_MAX_DRAW, 'Invalid event-box draw');
  return md5(JSON.stringify([value.eventBoxId,value.drawCount]));
}
