const TAKARAKUJI_DRAW_AT = new Map([
  [56000000002,1545292800], // 2018-12-20, archived top.json
  [56000000011,1689580800], // 2023-07-17, final message.enc
]);
const takarakujiRankCount = id => id === 56000000001 ? 8 : 6;
const takarakujiDrawAt = (id,event) => TAKARAKUJI_DRAW_AT.get(id) ??
  Math.max(event.startAt + 1,event.endAt - 14 * 86400);
function takarakujiOfflineRank(id,number,rankCount) {
  // shortcut: geometric local odds preserve the observed lowest-rank-heavy
  // shape; replace only if original winning numbers or odds are recovered.
  const range=10 ** (rankCount - 1),roll=crypto.createHash('sha256')
    .update(`${TAKARAKUJI_RESULT_POLICY}:${id}:${number}`).digest().readUInt32BE(0) % range;
  for(let rank=1;rank<rankCount;rank++) if(roll < 10 ** (rank - 1)) return rank;
  return rankCount;
}
