  // Divisor10000 comes from raw43283e0 relocation ->34a8204. No kind1/8
  // special scaling/minimum:22d373c explicitly passes false for dispatch.
  // All components are required. Missing providers are NOT zero modifiers.
  if (![base,percent,flat].every(pcStatVector)) fail(503,'Incomplete native PC status components');
  const stats = Object.fromEntries(PC_STAT_KINDS.map(kind=>[kind,
    (base[kind]+Math.trunc(Math.imul(base[kind],percent[kind])/10000)+flat[kind])|0]));
  const total = DISPATCH_STAT_KINDS.reduce((n,kind)=>(n+stats[kind])|0,0);
  return { stats,total };
