      //259cab8: a later rank qualifies immediately; positive ascension
      // threshold is an independent branch, not an extra AND condition.
      const eligible=row.jobRank<context.jobRank || (row.heroSublimateLevel>0 ?
        row.heroSublimateLevel<=context.heroSublimateLevel : row.level<=context.level &&
        row.jobRank<=context.jobRank && row.limitbreakCount<=context.limitbreakCount &&
        (row.limitbreakCount<context.limitbreakCount || context.isBoardComplete));
      if (!eligible) continue;
      //259cf94 mode1 replaces with the LAST matching child. Other modes
      // stack by mask, retaining the first child's mode even if it differs.
      if (ability.kind===1) expanded.clear();
