    const field = table === 'UserCharacterCostume' ? 'costumeId' : 'voiceId';
    for (const source of [existing,rows]) requireValue(source.every(row => row && Number.isSafeInteger(row[field]) &&
      row[field] > 0 && row[field] <= 0x7fffffff) && new Set(source.map(row => row[field])).size === source.length,
    'Invalid or duplicate saved costume/voice identity');
