    requireValue(source.every(row => row && Number.isSafeInteger(row.slotIndex) &&
      (row.slotIndex >= 1 && row.slotIndex <= 500 || row.slotIndex >= 10001 && row.slotIndex <= 10500)) &&
      new Set(source.map(row => row.slotIndex)).size === source.length, 'Invalid or duplicate saved equipment slot');
