    if(valisState) {drawState.policy='offline-event-box-v4';drawState.rewardStocks=rewardStocks;drawState.valisFloorHash=md5(JSON.stringify(valisState));}
    const parameters = { consumedItem: { itemId, amount }, chosenItems, UserEventBoxContent: awardedCounts,
      UserEventBoxStep: [targetStep], currentStepContents: eventBoxRates(step, counts,targetStep) };
    const operation = store.issueOperation(15000, parameters,signatureStocks.map(row=>row.beforeSignature));
    for(const stock of signatureStocks) stock.signature=operation.signature;
    const gachaDatesAdded=rewardStocks.filter(row=>Object.hasOwn(row,'beforeDates')).map(row=>({itemId:row.itemId,amount:0})),
      stockAmountAdded=rewardStocks.filter(row=>!Object.hasOwn(row,'beforeDates')).map(row=>({itemId:row.itemId,amount:0,
        signature:Object.hasOwn(row,'beforeSignature')?row.signature:null}));
    store.db.prepare('INSERT INTO event_box_request(operation_id,body_hash,box_id,item_id,remaining,total_count,bonus_state,draw_state,reward_seen,gacha_dates_added,stock_amount_added,valis_state) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)')
      .run(operation.id, hash, value.eventBoxId, itemId, stock[0].amount - amount, savedBox.totalDrawCount + amount,
        bonus?JSON.stringify(bonus):null,JSON.stringify(drawState),rewardStocks.length || valisState?'[]':null,
        gachaDatesAdded.length?JSON.stringify(gachaDatesAdded):null,stockAmountAdded.length?JSON.stringify(stockAmountAdded):null,
        valisState?JSON.stringify(valisState):null);
    for (const reward of rewards) store.db.prepare(`INSERT INTO event_box_reward_claim
      (operation_id,item_id,table_name,id_field,cumulative_amount,amount,before_cumulative) VALUES(?,?,?,?,?,?,?)`)
      .run(operation.id,reward.itemId,reward.table,reward.field,reward.cumulative,reward.amount,reward.beforeCumulative);
